            new Quote { Id = "https://es.wikiquote.org/wiki/Vicente_Aleixandre", Text = "Somos la luz unida, esa espada en la sombra que inmóvil va a abrasarse, va a derretirse unida cuando las llamas lleguen.", Author = "Vicente Aleixandre" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Vicente_Aleixandre", Text = "Quiero amor o la muerte, quiero morir del todo, quiero ser tú, tu sangre, esa larva rugiente que regando encerrada bellos miembros extremos siente así los hermosos límites de la vida.", Author = "Vicente Aleixandre" },
